-- Limpieza total y recarga completa de public.exportacion_analisis desde cosecha supabase.xlsx.
-- Ejecutar despues de supabase_cosecha_analisis.sql.
-- Borra toda la tabla exportacion_analisis y vuelve a insertar todos los datos de BD EXPORTACION SUPA.
-- porcentaje_expo se calcula como exportados_kg / kg_en_proceso.

begin;

delete from public.exportacion_analisis;





-- Renormaliza exportacion contra public.campos.

with matches as (
  select
    ea.id,
    array_agg(c.id order by c.potrero, c.bloque) as campo_ids,
    string_agg(distinct c.especie, ' / ' order by c.especie) as especie_match
  from public.exportacion_analisis ea
  join public.campos c
    on public.agrocore_normalizar_texto(c.variedad) = public.agrocore_normalizar_texto(ea.variedad)
   and (
        public.agrocore_normalizar_texto(c.potrero) = public.agrocore_normalizar_texto(ea.potrero_normalizado)
        or (public.agrocore_normalizar_texto(ea.potrero_normalizado) = '27' and public.agrocore_normalizar_texto(c.potrero) like '27%')
        or (public.agrocore_normalizar_texto(ea.potrero_normalizado) = '26' and public.agrocore_normalizar_texto(c.potrero) in ('d','e','f','g','h','i','j'))
      )
  where ea.archivo_origen = 'cosecha supabase.xlsx'
  group by ea.id
)
update public.exportacion_analisis ea
set campo_ids = m.campo_ids,
    especie = coalesce(nullif(ea.especie, ''), m.especie_match)
from matches m
where ea.id = m.id;

commit;

select count(*) as filas_exportacion, sum(desecho_kg) as total_desecho, avg(porcentaje_expo) as promedio_exportacion from public.exportacion_analisis where archivo_origen = 'cosecha supabase.xlsx';
